{"command":"$ErrorActionPreference='Continue'
$roots = @('C:\Users\spay\AppData\Local\Programs','C:\Program Files','C:\Program Files (x86)','C:\Users\spay\AppData\Local')
$found = @()
foreach ($r in $roots) {
  Get-ChildItem -Path $r -Recurse -Filter 'app.asar' -File -ErrorAction SilentlyContinue -Depth 4 |
    ForEach-Object {
      $found += [pscustomobject]@{
